CREATE TABLE IF NOT EXISTS users(username TEXT PRIMARY KEY,role TEXT NOT NULL,salt TEXT NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,username TEXT NOT NULL REFERENCES users(username),csrf TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(seq INTEGER PRIMARY KEY,at TEXT NOT NULL,actor TEXT NOT NULL,role TEXT NOT NULL,stream TEXT NOT NULL,action TEXT NOT NULL,payload TEXT NOT NULL,previous TEXT NOT NULL,hash TEXT NOT NULL,signature TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS batches(id TEXT PRIMARY KEY,source TEXT NOT NULL,class TEXT NOT NULL,received_at TEXT NOT NULL,rows INTEGER NOT NULL,hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS telemetry(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES batches(id),asset_id TEXT NOT NULL,kind TEXT NOT NULL,at TEXT NOT NULL,value DOUBLE PRECISION NOT NULL,unit TEXT NOT NULL,UNIQUE(asset_id,kind,at));
CREATE TABLE IF NOT EXISTS credits(id TEXT PRIMARY KEY,username TEXT NOT NULL REFERENCES users(username),intervention TEXT NOT NULL,amount INTEGER NOT NULL,at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nexus_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(ip_hash TEXT PRIMARY KEY,at BIGINT NOT NULL,count INTEGER NOT NULL);

CREATE OR REPLACE FUNCTION nexus_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION '% records are append-only', TG_TABLE_NAME; END;
$$;
DROP TRIGGER IF EXISTS audit_append_only ON audit;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE OR TRUNCATE ON audit FOR EACH STATEMENT EXECUTE FUNCTION nexus_append_only();
DROP TRIGGER IF EXISTS telemetry_append_only ON telemetry;
CREATE TRIGGER telemetry_append_only BEFORE UPDATE OR DELETE OR TRUNCATE ON telemetry FOR EACH STATEMENT EXECUTE FUNCTION nexus_append_only();
DROP TRIGGER IF EXISTS credits_append_only ON credits;
CREATE TRIGGER credits_append_only BEFORE UPDATE OR DELETE OR TRUNCATE ON credits FOR EACH STATEMENT EXECUTE FUNCTION nexus_append_only();
